const t=k=>dictionary[lang][k]||k,locale=()=>({kk:'kk-KZ',ru:'ru-RU',en:'en-GB'}[lang]);const monthNames={kk:['қаңтар','ақпан','наурыз','сәуір','мамыр','маусым','шілде','тамыз','қыркүйек','қазан','қараша','желтоқсан'],ru:['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'],en:['January','February','March','April','May','June','July','August','September','October','November','December']},dayNames={kk:['Жексенбі','Дүйсенбі','Сейсенбі','Сәрсенбі','Бейсенбі','Жұма','Сенбі'],ru:['Воскресенье','Понедельник','Вторник','Среда','Четверг','Пятница','Суббота'],en:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']};function dt(date,options={}){const key=typeof date==='string'?date:S.localDate(date),[y,m,d]=key.split('-').map(Number),day=new Date(key+'T12:00:00+05:00').getUTCDay(),hasMonth=!Object.prototype.hasOwnProperty.call(options,'month')||options.month!==undefined,dayName=options.weekday?dayNames[lang][day]:'';return (dayName?(options.weekday==='short'?({kk:['Жс','Дс','Сс','Ср','Бс','Жм','Сб'],ru:['Вс','Пн','Вт','Ср','Чт','Пт','Сб'],en:['Sun','Mon','Tue','Wed','Thu','Fri','Sat']}[lang][day]):dayName)+', ':'')+d+(hasMonth?' '+monthNames[lang][m-1]:'')}function clock(date=new Date()){return new Intl.DateTimeFormat(locale(),{timeZone:'Asia/Almaty',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(date)}function duration(m){let d=Math.floor(m/1440),h=Math.floor(m%1440/60),n=m%60;return [d?d+' '+t('day'):'',h?h+' '+t('hour'):'',(!d||n)?n+' '+t('minute'):''].filter(Boolean).join(' ')}function title(l){return S.subjects[l.subject][lang]}function locationText(l){return l.room==='online'?t('online'):l.room==='№93'?t('school'):t('building')+' · '+l.room+' '+t('room')}function line(l){return `${l.start}–${l.end} · ${title(l)}\n${t(l.type)} · ${l.teacher}\n${locationText(l)}`}
function nextAnswer(now=new Date()){let s=S.state(now,repeat),a=`${t('currentTime')}: ${dt(now,{weekday:'long'})}, ${clock(now)}.\n\n`;if(s.current)a+=`${t('now')}:\n${line(s.current)}\n${t('left')}: ${duration(s.remaining)}.\n\n`;else a+=(s.today.length&&s.today.every(l=>l.ends<=now)?t('todayFinished'):!s.today.length?t('freeToday'):'')+'\n\n';if(s.next)a+=`${t('next')}: ${dt(s.next.date,{weekday:'long'})}\n${line(s.next)}\n${t('wait')}: ${duration(s.wait)}.`;else a+=t('noneNext');return a.trim()}
function logo(){return `<div class="logo"><span class="logo-mark">✦</span><span>SMART.<b>Buddy</b></span></div>`}function mascot(){return '<div class="mascot"><div class="antenna"></div><div class="eyes"><i></i><i></i></div><div class="smile"></div><div class="hand"></div><div class="hand right"></div><div class="foot"></div><div class="foot right"></div></div>'}function nav(){return Object.keys({home:1,schedule:1,chat:1,gpa:1,tasks:1,office:1}).map((k,i)=>`<button class="${currentView===k?'active':''}" data-view="${k}"><span class="ico">${['▦','▣','✧','◴','☑','▤'][i]}</span>${t(k)}</button>`).join('')}
function render(){document.documentElement.lang=lang;document.title='SMART.Buddy — '+t(currentView);$('#app').innerHTML=`<div class="app"><aside class="sidebar">${logo()}<div class="uni">${t('subtitle')}</div><div class="nav-label">${t('campus')}</div><nav class="nav">${nav()}</nav><div class="side-bottom"><div class="help"><strong>${t('help')} ✦</strong><p>${t('helpSub')}</p><button data-view="chat">${t('talk')} ↗</button></div><div class="profile"><div class="avatar">АА</div><div><strong style="font-size:11px">Айару Амангелди</strong><small>ENU · 2026–2027</small></div></div></div></aside><main class="content"><header class="topbar"><div class="crumb">${t('campus')} <span>/ &nbsp; ${t(currentView)}</span></div><div class="mobile-logo">${logo()}</div><div class="top-actions"><div class="header-clock"><span class="live" id="clock"></span><small>${t('live')}</small></div><select id="lang" class="lang" aria-label="Language"><option value="kk" ${lang==='kk'?'selected':''}>ҚАЗ</option><option value="ru" ${lang==='ru'?'selected':''}>РУС</option><option value="en" ${lang==='en'?'selected':''}>ENG</option></select><div class="avatar" style="width:32px;height:32px;font-size:10px">АА</div></div></header><div id="pageContent">${pageContent()}</div><footer class="footer"><span>© 2026 ${t('footer')}</span><span>${t('unofficial')}</span></footer></main></div>`;$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('#lang').onchange=e=>{lang=e.target.value;save('buddy_lang',lang);render()};bind();tick();}
function intro(head,sub){return `<div class="intro"><div><h1>${head}</h1><p>${sub}</p></div></div>`}function suggestions(){return `<div class="suggestions">${['askNext','askTomorrow','askWeek'].map(k=>`<button data-question="${k}">${t(k)} ↗</button>`).join('')}</div>`}function chatInput(id){return `<form class="chat-input" id="${id}"><input aria-label="${t('input')}" placeholder="${t('input')}" required maxlength="500"><button aria-label="${t('send')}">↑</button></form>`}function lessonHTML(l,now=new Date()){let past=l.ends<=now,active=l.starts<=now&&!past;return `<div class="lesson ${active?'live-lesson':past?'past':''}"><div class="time">${l.start}<small>${l.end}</small></div><div class="lesson-detail"><strong>${esc(title(l))}</strong><small>${t(l.type)} · ${esc(l.teacher)}</small><small style="display:block;margin-top:5px">${esc(l.room==='№93'?t('school'):l.room==='online'?t('online'):t('building'))}</small></div><div class="room ${l.room==='online'?'badge-online':''}">${l.room==='online'?'◉':l.room==='№93'?'№93':'⌖ '+l.room}<span style="display:block;margin-top:4px">${active?t('current'):past?t('ended'):t('upcoming')}</span></div></div>`}function empty(date){return `<div class="empty">🌿<p>${date<'2026-09-01'||date>'2026-12-12'||(!repeat&&(date<'2026-11-02'||date>'2026-11-08'))?t('outside'):t('empty')}</p></div>`}function rows(date){let ls=S.events(date,repeat);return ls.length?ls.map(l=>lessonHTML(l)).join(''):empty(date)}
function pageContent(){if(currentView==='home')return `${intro(t('hello'),t('intro'))}<div class="grid"><div><div class="hero"><div class="eyebrow"><i></i>SMART.BUDDY · ${t('source')}</div><h2>${t('hero')}</h2><p>${t('heroSub')}</p><button class="primary" data-view="chat">${t('talk')} &nbsp; ✧</button>${mascot()}<div class="bubble">${t('encourage')}</div></div><div class="stats"><div class="stat" data-view="gpa"><div class="stat-top">◴<span class="pill">GPA</span></div><div class="stat-label">${t('gpaTitle')}</div><div class="stat-value">${gpaValue()} <small>/4.00</small></div></div><div class="stat" data-view="schedule"><div class="stat-top">▣</div><div class="stat-label">${t('count')}</div><div class="stat-value" id="todayCount"></div></div><div class="stat" data-view="tasks"><div class="stat-top">☑</div><div class="stat-label">${t('deadlines')}</div><div class="stat-value">${tasks.filter(x=>!x.done).length}</div></div></div><div class="section-title"><h2>${t('today')}</h2><button class="text-btn" data-view="schedule">${t('allSchedule')}</button></div><div class="schedule" id="homeLessons"></div><div class="quick"><button id="whereBtn">⌖ ${t('where')}</button><button data-view="gpa">◴ ${t('gpa')}</button><button data-view="office">▤ ${t('office')}</button></div><p class="source-note">${t('sourceNote')}</p></div><div class="right-col"><div class="panel"><div class="chat-head"><div class="mini-bot">✧</div><div><h3>${t('assistant')}</h3><small>${t('assistantSub')}</small></div></div><div class="chat-bubble home-next" id="nextSummary"></div>${suggestions()}${chatInput('quickChat')}</div><div class="panel"><div class="section-title"><h3>${t('tasks')}</h3><button data-view="tasks" class="text-btn">↗</button></div>${taskList(true)}</div><div class="event"><small>SMART.ENU → BUDDY</small><h3>${t('sourceTitle')}</h3><p class="muted">${t('imported')}</p><button data-view="schedule">${t('allSchedule')}</button></div></div></div>`;
if(currentView==='schedule')return `${intro(t('schedule'),t('source'))}<div class="view-card"><div class="day-select"><h2 style="margin:0">${dt(selectedDate,{weekday:'long'})}</h2><label class="credit-label">${t('calendar')}<input type="date" id="datePicker" value="${selectedDate}" min="2026-09-01" max="2026-12-12"></label></div><div class="tabs">${[1,2,3,4,5,6,0].map((n,i)=>{let d=new Date(selectedDate+'T12:00:00+05:00').getUTCDay(),m=S.shift(selectedDate,-((d+6)%7)),date=S.shift(m,i);return `<button data-date="${date}" class="${selectedDate===date?'active':''}">${dt(date,{weekday:'short',month:undefined})}</button>`}).join('')}</div><div id="dayLessons">${rows(selectedDate)}</div></div><div class="view-card"><h3>${t('sourceTitle')}</h3><p class="muted">${t('imported')} · 01.09–12.12.2026</p><label class="toggle"><input id="repeat" type="checkbox" ${repeat?'checked':''}>${t('weekly')}</label><p class="source-note">${t('sourceNote')}</p></div>`;
if(currentView==='chat')return `${intro(t('chat'),t('assistantSub'))}<div class="view-card full-chat"><div class="chat-head"><div class="mini-bot">✧</div><div><h3>Buddy</h3><small>${t('live')}</small></div></div><div class="chat-log" id="chatLog"><div class="chat-bubble">${t('welcome')}</div>${messages.map(m=>`<div class="chat-bubble ${m.user?'user':''}">${esc(m.user?m.text:respond(m.question))}</div>`).join('')}</div><div class="chat-actions">${['askNext','askToday','askTomorrow','askWeek','timeQuestion'].map(k=>`<button data-question="${k}">${t(k)}</button>`).join('')}</div>${chatInput('chatForm')}<p class="source-note">${t('assistantNote')} ${t('offlineAnswer')}</p></div>`;
if(currentView==='tasks')return `${intro(t('tasks'),t('taskNote'))}<button class="primary" id="addTask">${t('addTask')}</button><div class="view-card" style="margin-top:20px">${taskList(false)}</div>`;
if(currentView==='gpa')return `${intro(t('gpa'),t('gpaIntro'))}<div class="view-card"><h2>${t('gpaTitle')}</h2><div class="gpa-row credit-label"><span>${t('course')}</span><span>${t('credits')}</span><span>${t('grade')}</span></div><div id="gpaRows">${courseRows()}</div><button class="text-btn" id="addCourse">${t('addCourse')}</button><div class="result" id="gpaResult">GPA <strong style="font-size:28px">${gpaValue()}</strong> / 4.00</div></div><div class="view-card"><h2>${t('exam')}</h2><p class="muted">${t('examNote')}</p><div class="form-grid"><label>${t('rating')}<input type="number" id="rating" value="85" min="0" max="100"></label><label>${t('target')}<input type="number" id="target" value="90" min="0" max="100"></label></div><button class="primary" id="calcExam">${t('calculate')}</button><div class="result" id="examResult">${t('examMin')}</div></div>`;
if(currentView==='office')return `${intro(t('office'),t('officeNote'))}<div class="view-card"><span class="tag">${t('demo')}</span><h2 style="margin-top:20px">${t('officeTitle')}</h2><form id="certForm"><div class="form-grid"><label>${t('fullName')}<input name="name" value="Айару Амангелди" required></label><label>${t('purpose')}<input name="purpose" value="${t('purposeValue')}" required></label></div><button class="primary">${t('demoSubmit')}</button></form><div id="certResult"></div></div>`;}
function view(id){currentView=id;render();window.scrollTo({top:0,behavior:'smooth'})}function tick(){let s=S.state(new Date(),repeat);if($('#clock'))$('#clock').textContent=clock(s.now);if($('#todayCount'))$('#todayCount').textContent=s.today.length;if($('#homeLessons'))$('#homeLessons').innerHTML=rows(s.date);if($('#nextSummary'))$('#nextSummary').textContent=nextAnswer(s.now);if($('#dayLessons'))$('#dayLessons').innerHTML=rows(selectedDate)}
const aliases={modern:['қазіргі','современ','modern','бағдарламалау тіл','язык программ'],olympiad:['олимпиад','olympiad','competitive'],printing:['3d','3 д','принт','print','модельдеу','моделир'],android:['android','андроид','мобиль','mobile'],bigdata:['big data','үлкен дерек','больш','bigdata'],integration:['жаратылыстану','интеграци','natural science'],vr:['виртуал','кеңейтілген','дополненн','virtual','augmented','vr','ar/vr'],info:['инфограф','infograph']};
function respond(q){let s=q.toLowerCase(),now=new Date(),date=S.localDate(now),prefix=`${t('currentTime')}: ${clock(now)}\n\n`;if(/сағат|который час|врем[яе] сейчас|what time|time now/.test(s)&&!/сабақ|пара|class/.test(s))return prefix.trim();if(/gpa|балл|оцен|grade|score|баға/.test(s))return t('gpaIntro')+'\n'+t('examNote');if(/справ|декан|анықтама|enrollment|office/.test(s))return t('officeNote');if(/дедлайн|тапсырма|задач|deadline|task/.test(s))return tasks.filter(x=>!x.done).map(x=>`${x.title} · ${x.date}`).join('\n')||t('noTasks');
let dayOffset=/ертең|завтра|tomorrow/.test(s)?1:/бүрсігүн|послезавтра|day after tomorrow/.test(s)?2:null; // handle longer phrases before tomorrow
if(/бүрсігүн|послезавтра|day after tomorrow/.test(s))dayOffset=2;
const dayAliases=[['жексен','воскрес','sunday'],['дүйсен','понедель','monday'],['сейсен','вторник','tuesday'],['сәрсен','сред','wednesday'],['бейсен','четвер','thursday'],['жұма','пятниц','friday'],['сенбі','суббот','saturday']];let explicit=dayAliases.findIndex(a=>a.some(x=>s.includes(x)));let requestedDate=dayOffset!==null?S.shift(date,dayOffset):explicit>=0?S.shift(date,(explicit-new Date(date+'T12:00:00+05:00').getUTCDay()+7)%7):date;
let subj=Object.keys(aliases).find(k=>aliases[k].some(a=>s.includes(a)));if(subj){let ev=[];if(dayOffset!==null||explicit>=0||/бүгін|сегодня|today/.test(s)){ev=S.events(requestedDate,repeat).filter(l=>l.subject===subj);if(!ev.length)return prefix+dt(requestedDate,{weekday:'long'})+'\n'+S.subjects[subj][lang]+'\n'+t('empty')}else for(let i=0;i<100&&!ev.length;i++)ev=S.events(S.shift(date,i),repeat).filter(l=>l.subject===subj&&l.ends>now);return prefix+(ev.length?`${t('nextDate')}: ${dt(ev[0].date,{weekday:'long'})}\n\n`+ev.map(line).join('\n\n')+`\n\n${ev[0].starts>now?t('wait')+': '+duration(Math.ceil((ev[0].starts-now)/60000)):ev[0].ends<=now?t('ended'):t('now')}`:t('noneNext'))}
if(/апта|недел|week/.test(s)){let day=new Date(date+'T12:00:00+05:00').getUTCDay(),m=S.shift(date,-((day+6)%7));return Array.from({length:7},(_,i)=>{let d=S.shift(m,i),ev=S.events(d,repeat);return `${dt(d,{weekday:'long'})}\n${ev.length?ev.map(l=>`${l.start}–${l.end} · ${title(l)} · ${l.room==='online'?t('online'):l.room}`).join('\n'):t('empty')}`}).join('\n\n')}
if(dayOffset!==null||explicit>=0||/бүгін|сегодня|today/.test(s)){let ev=S.events(requestedDate,repeat);return prefix+dt(requestedDate,{weekday:'long'})+'\n\n'+(ev.length?ev.map(line).join('\n\n'):t('empty'))}
if(/келесі|сабақ|қашан|қанша|қайда|пара|пары|урок|когда|следующ|сколько|class|lesson|next|when|where|распис|кесте|schedule|timetable/.test(s))return nextAnswer(now);return t('fallback')}
function ask(q){if(!q.trim())return;messages.push({user:true,text:q},{user:false,question:q});currentView='chat';render();$('#chatLog').scrollTop=$('#chatLog').scrollHeight;$('#chatForm input').focus()}
function taskList(short){let list=short?tasks.filter(x=>!x.done).slice(0,3):tasks;return list.length?list.map(x=>`<label class="task ${x.done?'done':''}"><input class="check" type="checkbox" data-task="${x.id}" ${x.done?'checked':''}><div><strong>${esc(x.title)}</strong><small>${esc(x.subject||'')}</small><span class="task-time">${x.done?t('done'):esc(x.date)}</span></div></label>`).join(''):`<p class="muted">${t('noTasks')}</p>`}
function gpaValue(){let credits=courses.reduce((s,c)=>s+(+c.credits||0),0);return credits?(courses.reduce((s,c)=>s+c.credits*c.grade,0)/credits).toFixed(2):'0.00'}const points=[['A',4],['A−',3.67],['B+',3.33],['B',3],['B−',2.67],['C+',2.33],['C',2],['C−',1.67],['D+',1.33],['D',1],['F',0]];function courseRows(){return courses.map((c,i)=>`<div class="gpa-row"><input value="${esc(c.name)}" data-name="${i}" aria-label="${t('course')}"><input type="number" min="1" max="30" value="${c.credits}" data-credit="${i}" aria-label="${t('credits')}"><select data-grade="${i}" aria-label="${t('grade')}">${points.map(p=>`<option value="${p[1]}" ${+c.grade===p[1]?'selected':''}>${p[0]} · ${p[1]}</option>`).join('')}</select><button data-remove="${i}" aria-label="${t('remove')}">×</button></div>`).join('')}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}let previousFocus;function modal(html){previousFocus=document.activeElement;$('#modalContent').innerHTML=html;$('#modalBg').style.display='flex';$('#modalBg .modal').setAttribute('aria-label',t('demo'));$('#closeModal').setAttribute('aria-label',lang==='kk'?'Жабу':lang==='ru'?'Закрыть':'Close');$('#closeModal').focus()}function closeModal(){$('#modalBg').style.display='none';previousFocus?.focus()}$('#closeModal').onclick=closeModal;$('#modalBg').onclick=e=>{if(e.target.id==='modalBg')closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modalBg').style.display==='flex'){let f=[...$('#modalBg').querySelectorAll('button,input,select')],first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function bind(){$$('[data-question]').forEach(b=>b.onclick=()=>ask(t(b.dataset.question)));['quickChat','chatForm'].forEach(id=>{if($('#'+id))$('#'+id).onsubmit=e=>{e.preventDefault();ask(e.target.querySelector('input').value)}});if($('#datePicker'))$('#datePicker').onchange=e=>{if(e.target.value){selectedDate=e.target.value;render()}};$$('[data-date]').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;render()});if($('#repeat'))$('#repeat').onchange=e=>{repeat=e.target.checked;save('buddy_repeat',repeat);render()};if($('#whereBtn'))$('#whereBtn').onclick=()=>{let state=S.state(new Date(),repeat),l=state.current||state.next;modal(`<h2>${t('where')}</h2><p class="muted">${l?esc(title(l))+'<br>'+esc(locationText(l)):t('noneNext')}</p><p class="source-note">${l?.room==='online'?t('onlineNote'):t('locationNote')}</p>`)};$$('[data-task]').forEach(c=>c.onchange=()=>{tasks.find(t=>t.id===+c.dataset.task).done=c.checked;save('buddy_tasks',tasks);render()});if($('#addTask'))$('#addTask').onclick=()=>{modal(`<h2>${t('addTask')}</h2><form id="taskForm"><label>${t('taskTitle')}<input name="title" maxlength="100" required></label><label>${t('subject')}<select name="subject">${Object.values(S.subjects).map(s=>`<option>${s[lang]}</option>`).join('')}</select></label><label>${t('due')}<input type="date" name="date" value="${S.localDate()}" required></label><button class="primary">${t('add')}</button></form>`);$('#taskForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);tasks.push({id:Date.now(),title:f.get('title'),subject:f.get('subject'),date:f.get('date'),done:false});save('buddy_tasks',tasks);closeModal();render();toast(t('taskSaved'))}};
if($('#addCourse'))$('#addCourse').onclick=()=>{courses.push({name:t('course'),credits:3,grade:4});save('buddy_courses',courses);render()};function calc(){save('buddy_courses',courses);$('#gpaResult').textContent=courses.some(c=>c.credits<1||c.credits>30)?t('invalidCredit'):'GPA: '+gpaValue()+' / 4.00'}$$('[data-name]').forEach(x=>x.oninput=()=>{courses[+x.dataset.name].name=x.value;save('buddy_courses',courses)});$$('[data-credit]').forEach(x=>x.oninput=()=>{courses[+x.dataset.credit].credits=+x.value;calc()});$$('[data-grade]').forEach(x=>x.onchange=()=>{courses[+x.dataset.grade].grade=+x.value;calc()});$$('[data-remove]').forEach(x=>x.onclick=()=>{courses.splice(+x.dataset.remove,1);save('buddy_courses',courses);render()});if($('#calcExam'))$('#calcExam').onclick=()=>{let r=+$('#rating').value,v=+$('#target').value;if(!$('#rating').value||!$('#target').value||r<0||r>100||v<0||v>100){$('#examResult').textContent=t('invalid');return}let n=(v-r*.6)/.4;$('#examResult').textContent=n>100?t('impossible')+': '+(r*.6+40).toFixed(1):t('need')+': '+Math.max(0,Math.ceil(n*10)/10)+' /100. '+t('examMin')};if($('#certForm'))$('#certForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),r={id:'DEMO-'+Date.now().toString().slice(-6),name:f.get('name'),purpose:f.get('purpose')};save('buddy_certificate',r);$('#certResult').innerHTML=`<div class="result">${t('saved')} · ${r.id}<br>${esc(r.name)}<br>${t('officeNote')}</div>`}}

